def norm(s):
    s = unicodedata.normalize("NFKC", s)
    s = s.replace("ﬁ", "fi").replace("ﬂ", "fl").replace("ﬀ", "ff").replace("ﬃ", "ffi").replace("ﬄ", "ffl")
    # Remove line-break hyphenation in extracted text
    s = re.sub(r"-\s+", "", s)
    # Collapse kerning artifacts like "UA V" -> "UAV"
    s = re.sub(r"\bUA\s+V", "UAV", s)
    s = re.sub(r"\s+", " ", s).strip()
    return s

def norm_loose(s):
    return re.sub(r"\s+", "", norm(s)).lower()

