    raw = "".join(ch for ch in raw if ch in "\n\t" or ord(ch) >= 32)
    pages = raw.split("=== PDF PAGE ")
    page_map = {}
    for p in pages[1:]:
        pnum = int(p.splitlines()[0].split()[0])
        page_map[pnum] = p

    checks = [("identity_evidence", rec["identity_evidence"], 1, 45),
              ("alignment", rec["alignment"], 10, 45)]
    for gname, gobj in rec["gates"].items():
        minw = 1 if gname == "date_window" else 10
        checks.append((f"gate:{gname}", gobj, minw, 45))

    for label, obj, minw, maxw in checks:
        wc = len(obj["quote"].split())
        if not (minw <= wc <= maxw):
            print(f"WORD COUNT FAIL {rid} {label}: {wc} not in [{minw},{maxw}]")
        p = obj["page"]
        ptext = page_map.get(p, "")
        if norm_loose(obj["quote"]) not in norm_loose(ptext):
            print(f"QUOTE NOT FOUND {rid} {label} on page {p}: {obj[\"quote\"]}")
        else:
            print(f"OK {rid} {label} (p.{p}, {wc}w)")
