def norm_page(s):
    s = unicodedata.normalize("NFKC", s)
    s = s.replace("ﬁ", "fi").replace("ﬂ", "fl").replace("ﬀ", "ff").replace("ﬃ", "ffi").replace("ﬄ", "ffl")
    # Convert line-break hyphens into a regex-friendly form: check both stripped and kept
    s = re.sub(r"\bUA\s+V", "UAV", s)
    return s

def check_quote(q, ptext):
    pt = norm_page(ptext)
    # Build regex from q where hyphens can match optional hyphen + whitespace
    q_norm = unicodedata.normalize("NFKC", q)
    tokens = re.split(r"(\s+|-)", q_norm)
    pat = ""
    for t in tokens:
        if t == "":
            continue
        elif t.isspace():
            pat += r"(?:-\s+|\s+)"
        elif t == "-":
            pat += r"-\s*"
        else:
            # Allow line-wrap hyphenation inside a word too
            pat += r"(?:-\s*)?".join(re.escape(ch) for ch in t)
    return re.search(pat, pt, flags=re.IGNORECASE) is not None

