    raw = open(f"screening_46/text/{rid}.txt", "rb").read().decode("utf-8", errors="replace")
    raw = "".join(ch for ch in raw if ch in "\n\t" or ord(ch) >= 32)
    pages = raw.split("=== PDF PAGE ")
    page_map = {int(p.splitlines()[0].split()[0]): p for p in pages[1:]}
