def norm_page(s):
    s = unicodedata.normalize("NFKC", s)
    s = s.replace("ﬁ", "fi").replace("ﬂ", "fl").replace("ﬀ", "ff").replace("ﬃ", "ffi").replace("ﬄ", "ffl")
    s = re.sub(r"\bUA\s+V", "UAV", s)
    return re.sub(r"\s+", "", s).lower()

def norm_q(s):
    s = unicodedata.normalize("NFKC", s)
    return re.sub(r"\s+", "", s).lower()

for rec in payload["records"]:
    rid = rec["id"]
    raw = open(f"screening_46/text/{rid}.txt", "rb").read().decode("utf-8", errors="replace")
    raw = "".join(ch for ch in raw if ch in "\n\t" or ord(ch) >= 32)
    pages = raw.split("=== PDF PAGE ")
    page_map = {int(p.splitlines()[0].split()[0]): p for p in pages[1:]}
    checks = [("identity_evidence", rec["identity_evidence"], 1, 45),
              ("alignment", rec["alignment"], 10, 45)]
    for gname, gobj in rec["gates"].items():
        minw = 1 if gname == "date_window" else 10
        checks.append((f"gate:{gname}", gobj, minw, 45))
    for label, obj, minw, maxw in checks:
        wc = len(obj["quote"].split())
        qstr = obj["quote"]
        pnum = obj["page"]
        assert minw <= wc <= maxw, f"{rid} {label} wc={wc}"
        # compare stripped whitespace (ignoring line-wrap hyphens when comparing without hyphens)
        pt = norm_page(page_map[pnum])
        qn = norm_q(qstr)
        if qn not in pt:
            # try removing line-wrap hyphens from raw page first
            raw_no_wrap = re.sub(r"-\n\s*", "", page_map[pnum])
            pt2 = norm_page(raw_no_wrap)
            assert qn in pt2, f"NOT FOUND {rid} {label} p.{pnum}: {qstr}"
        assert "%" not in obj.get("rationale", "") and "%" not in qstr
