def norm_page(s):
    s = unicodedata.normalize("NFKC", s)
    s = s.replace("ﬁ", "fi").replace("ﬂ", "fl").replace("ﬀ", "ff").replace("ﬃ", "ffi").replace("ﬄ", "ffl")
    s = re.sub(r"\bUA\s+V", "UAV", s)
    return re.sub(r"\s+", "", s).lower()

def norm_q(s):
    s = unicodedata.normalize("NFKC", s)
    return re.sub(r"\s+", "", s).lower()

for rec in payload["records"]:
    rid = rec["id"]
    raw = open(f"screening_46/text/{rid}.txt", "rb").read().decode("utf-8", errors="replace")
    raw = "".join(ch for ch in raw if ch in "\n\t" or ord(ch) >= 32)
    pages = raw.split("=== PDF PAGE ")
    page_map = {int(p.splitlines()[0].split()[0]): p for p in pages[1:]}
    checks = [("identity_evidence", rec["identity_evidence"], 1, 45),
